<script module lang="ts">
/**
 * Notifications that report the outcome of an action (`design/components/toast.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  devWarning,
  getToasts,
  joinSlot,
  removeToast,
  toast,
  watchEffect,
  type ToastAction,
} from '@polymorph/svelte'

export interface ToasterMessages {
  dismiss: string
  notification: string
  viewport: string
}

export interface ToastProps {
  /**
   * At most one; a shortcut, never the only way to do what it does.
   */
  action?: ToastAction
  /**
   * Content supplied by the host, including current, controller-gated recovery controls.
   */
  content?: Snippet
  description?: string
  /**
   * Required recovery actions stay reachable until their owning state resolves.
   */
  dismissible?: boolean
  /**
   * `Infinity` pins the toast until it is dismissed. A call that sets neither this nor
   * `retained` takes its tone's lifetime (see `retained`); one that sets only `retained` gets
   * `TOAST_DEFAULT_DURATION_MS`.
   */
  durationMs?: number
  /**
   * A live toast's id updates it in place: same card and position, new content, timer restarted.
   * An unknown id raises a new toast. `toast.promise` uses this, not a special path.
   */
  id?: string
  /**
   * Called once when the toast leaves for a reason other than its owner's: the reader dismissed
   * it, its time ran out, `toast.dismiss` closed it, or a newer toast evicted it. Removing it
   * (`remove`) and updating it in place do not call it, because the owner already knows.
   */
  onDismiss?: () => void
  /**
   * State-owned notices are removed by their owner, never evicted by another notification. A
   * call that sets neither this nor `durationMs` takes its tone's lifetime: danger and warning
   * are retained and pinned, and the other tones leave after the default duration.
   */
  retained?: boolean
  title: string
  tone?: 'info' | 'warning' | 'success' | 'danger' | 'neutral'
}
</script>

<script lang="ts">
let {
  action,
  content,
  description,
  dismissible,
  durationMs,
  id: idOwn,
  onDismiss,
  retained,
  title,
  tone,
}: ToastProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const toastId = $derived(id ?? uid)
const options = $derived({
  id: toastId,
  title,
  description,
  tone,
  action,
  durationMs,
  dismissible,
  retained,
  content: content,
  onDismiss: () => onDismiss?.(),
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = toast(options)
  release1 = () => {
    removeToast(ran)
  }
}
watchEffect(effect1, { watch: () => [toastId, title] })
onDestroy(() => release1?.())
const effect2 = () => {
  getToasts().some((record) => record.id === toastId && record.closing !== true) && toast(options)
}
watchEffect(effect2, { watch: () => options, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const timer = setTimeout(() => {
    devWarning(
      document.querySelector('[data-toast-part="list"]') === null,
      `Toast "${title}" rendered with no Toast viewport mounted, so nothing draws it. Mount the viewport once at the application root, outside any error boundary whose fallback renders a Toast.`,
    )
  }, 0)
  release3 = () => clearTimeout(timer)
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
}{/if
}{@render joined.end?.()}
